		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		remoteHash := plumbing.NewHash(parts[0])
		remoteRefName := parts[1]

		localRef, refErr := s.repo.Reference(plumbing.ReferenceName(remoteRefName), true)
		if refErr == nil && localRef.Hash() == remoteHash {
			continue // Already up to date
		}

		refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", remoteRefName, remoteRefName))
	}

	if len(refSpecs) == 0 {
		return nil
